import{_ as t,o as s,c as i,a5 as r}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-3-system-health-monitoring/report3_spec_en.md","filePath":"feature/admin-management/3-10-3-system-health-monitoring/report3_spec_en.md"}'),n={name:"feature/admin-management/3-10-3-system-health-monitoring/report3_spec_en.md"};function o(a,e,l,c,u,g){return s(),i("div",null,[...e[0]||(e[0]=[r("<p><strong>§3.10.3 System Health Monitoring</strong></p><p><strong>Function Trigger</strong></p><p>Begins when an Administrator (ADMIN) accesses the monitoring page at /admin/system-health.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. Technical system administrator monitoring microservices infrastructure status.</li><li><strong>Purpose</strong>: Monitor operational status (UP, DEGRADED, DOWN), CPU/RAM utilization, and response latency across 7 microservices in the BrandHub platform.</li><li><strong>Interface</strong>: System Health Monitoring Screen (SCR-ADM-03), featuring a service status card grid, real-time resource consumption charts, and system incident alert log.</li><li><strong>Data Processing</strong>: The system dispatches health check requests (/actuator/health) to all 7 microservices (BR-65), measures response latency, collects CPU/RAM utilization, determines overall cluster health, and triggers alerts if any service fails.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — System Health Monitoring Screen (SCR-ADM-03):</p><ul><li>Left/Header: Sidebar Admin Navigation; Top Header displaying title &quot;System Health Monitoring&quot;, global status badge (&quot;7/7 Services Operational&quot;), and button &quot;Ping All Services&quot;.</li><li>Center: 7 microservice cards grid (api-gateway, auth-service, business-service, ai-service, publisher-service, notification-service, payment-service): Each card displays Service Name, Status Badge (UP in green, DEGRADED in yellow, DOWN in red), Response Latency (ms), % CPU, % RAM, Continuous Uptime; 24-hour historical latency chart; Recent Incident log table.</li><li>Buttons: Button &quot;Ping All Services&quot; (green), Button &quot;Refresh&quot;, Service Status Filter (All, Error, Warning).</li><li>Footer: Last check timestamp and auto-refresh interval indicator (default every 30 seconds).</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: None (system probes periodically every 30 seconds by default).</li><li><strong>Input optional</strong>: serviceName (filter by specific service), refreshInterval (refresh cycle: 10s, 30s, 60s).</li><li><strong>System data</strong>: servicesList (array of 7 services), status (UP, DEGRADED, DOWN), latencyMs, cpuUsagePercent, memoryUsagePercent, diskFreeBytes, lastPingTimestamp.</li><li><strong>Output</strong>: Detailed microservices health status list with HTTP status code 200 OK.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-65</strong>: Microservices system health monitoring is an exclusive technical domain restricted to the ADMIN role.</li><li><strong>BR-35</strong>: Authenticate ADMIN permissions before accepting requests and exposing sensitive infrastructure telemetry.</li><li><strong>BR-16</strong>: Service outage incidents or status transitions to DOWN/DEGRADED are automatically logged into the system audit log.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>User does not possess ADMIN role permissions -&gt; Display: <strong>MSG39</strong></li><li>Microservice is unresponsive or connection lost -&gt; Display: <strong>MSG38</strong></li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Admin navigates to System Health screen (/admin/system-health).</li><li>System validates ADMIN role authority under BR-35, BR-65.</li><li>System dispatches health check requests (/actuator/health) to 7 microservices.</li><li>System receives probe responses, computes latency, CPU, RAM, and determines individual service status.</li><li>System renders service statuses on SCR-ADM-03 with visual color badges.</li><li>System automatically re-checks and refreshes telemetry every 30 seconds.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: If user does not possess ADMIN role, system rejects access and displays MSG39.</li><li>4.a1: If a service fails to respond after 3,000ms, system marks status as DOWN (red badge) and displays MSG38.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Microservices telemetry is continuously refreshed and displayed on the monitoring interface.</li><li>Service interruption incidents are persisted in system_health_logs (BR-16).</li></ul>",14)])])}const d=t(n,[["render",o]]);export{m as __pageData,d as default};
